import datetime


_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    s = datetime.date.fromisoformat(start)
    sord = s.toordinal()
    monday_ord = sord - s.weekday()
    end = datetime.date(3000, 1, 1).toordinal()
    one_day = datetime.timedelta(days=1)
    seven_days = datetime.timedelta(days=7)
    start_month_idx = s.year * 12 + s.month

    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])

    def month_active(d: datetime.date) -> bool:
        return (d.year * 12 + d.month - start_month_idx) % k == 0

    if kind == "DAILY":
        def matches(d: datetime.date) -> bool:
            return (d.toordinal() - sord) % k == 0

    elif kind == "WEEKLY":
        days = {_WEEKDAYS[c] for c in parts[2].split(",")}

        def matches(d: datetime.date) -> bool:
            week = (d.toordinal() - monday_ord) // 7
            return week % k == 0 and d.weekday() in days

    elif kind == "MONTHLY" and len(parts) == 3:
        target = int(parts[2])

        def matches(d: datetime.date) -> bool:
            if not month_active(d):
                return False
            if target > 0:
                return d.day == target
            return (d + one_day).day == 1

    elif kind == "MONTHLY":
        nth = int(parts[2])
        wd = _WEEKDAYS[parts[3]]

        def matches(d: datetime.date) -> bool:
            if not month_active(d) or d.weekday() != wd:
                return False
            if nth > 0:
                return (d.day - 1) // 7 + 1 == nth
            return (d + seven_days).month != d.month

    else:  # YEARLY
        mm, dd = (int(x) for x in parts[2].split("-"))

        def matches(d: datetime.date) -> bool:
            return (d.year - s.year) % k == 0 and d.month == mm and d.day == dd

    result = []
    cur = sord
    while len(result) < count and cur < end:
        d = datetime.date.fromordinal(cur)
        if matches(d):
            result.append(d.isoformat())
        cur += 1
    return result
